; Crater character animation
; $5e45-$5e64

; Each frame, fills the characters $2a-$2b ($3150-$315f) with random bits: CIA 2 timer A low AND the mask $3160+x, OR $55. Then it calls $5ea0.
crater_chars_animate
        ldx #$00
crater_chars_loop
        txa
        and #$01
        bne crater_chars_odd            ; The even and the odd path both read $dd04.
        lda CI2TALO
